/**
 * Shared vocabulary for the one-time "How did you hear about us?" acquisition
 * survey (User.heardAboutUs). ONE definition of the channel keys, their friendly
 * labels, and the value validation — imported by the customer prompt
 * (components/customer/HeardAboutUsPrompt.tsx), the server action
 * (lib/actions-account.ts), the admin aggregate (app/admin/audience/page.tsx)
 * and the customer profile (app/admin/users/[id]/page.tsx) so none of the four
 * can drift out of step with the others.
 *
 * This module is intentionally framework-free (no "use server", no server-only
 * imports) so the client prompt can import the option list and labels too.
 *
 * Stored value shapes (User.heardAboutUs):
 *   null              — not yet asked / not yet answered
 *   "skipped"         — the customer dismissed the survey
 *   "<channel key>"   — one of HEARD_OPTIONS below (google, youtube, …, blog)
 *   "other:<text>"    — the free-text "Other" answer (text trimmed + capped)
 */

/** The selectable channels, in display order. "other" is handled separately
 *  because it carries a free-text tail; it is not in this list. */
export const HEARD_OPTIONS = [
  { key: "google", label: "Google Search" },
  { key: "youtube", label: "YouTube" },
  { key: "instagram", label: "Instagram" },
  { key: "tiktok", label: "TikTok" },
  { key: "facebook", label: "Facebook" },
  { key: "x", label: "X (Twitter)" },
  { key: "reddit", label: "Reddit" },
  { key: "friend", label: "Friend / word of mouth" },
  { key: "blog", label: "Blog / article" },
] as const;

export type HeardChannelKey = (typeof HEARD_OPTIONS)[number]["key"];

/** key → friendly label, including the "other" bucket. The single source the
 *  prompt, the aggregate and the profile all read from. */
export const HEARD_LABELS: Record<string, string> = {
  ...Object.fromEntries(HEARD_OPTIONS.map((o) => [o.key, o.label])),
  other: "Other",
};

/** Set of concrete channel keys that are valid on their own (no free text). */
const CHANNEL_KEYS = new Set<string>(HEARD_OPTIONS.map((o) => o.key));

/** Max length of the free-text tail on an "other:<text>" answer. */
export const HEARD_OTHER_MAX = 120;

/** Sanitize the free text a customer types into the "Other" box: drop control
 *  characters, collapse whitespace, trim and cap length. */
export function sanitizeHeardOther(text: string): string {
  const cleaned = Array.from(text)
    .filter((ch) => {
      const c = ch.codePointAt(0) ?? 0;
      // Drop C0 controls (incl. tab/newline) and DEL; keep everything else.
      return c >= 0x20 && c !== 0x7f;
    })
    .join("");
  return cleaned.replace(/\s+/g, " ").trim().slice(0, HEARD_OTHER_MAX);
}

/**
 * Validate/normalize a raw survey submission into a value safe to store, or
 * `null` when it is not a recognised answer (the action then no-ops rather than
 * writing garbage). Accepts a bare channel key, "skipped", or "other:<text>".
 */
export function normalizeHeardSource(raw: unknown): string | null {
  if (typeof raw !== "string") return null;
  const value = raw.trim();
  if (value === "skipped") return "skipped";
  if (CHANNEL_KEYS.has(value)) return value;
  if (value === "other" || value.toLowerCase().startsWith("other:")) {
    const tail = value.slice(value.indexOf(":") + 1);
    const text = value === "other" ? "" : sanitizeHeardOther(tail);
    return text ? `other:${text}` : "other";
  }
  return null;
}

/**
 * Friendly display label for a stored value. `null` → "—", "skipped" →
 * "Skipped", any "other:<text>" → "Other" (with the typed text appended when
 * `withOtherText`), otherwise the channel's friendly label.
 */
export function heardLabel(value: string | null | undefined, opts?: { withOtherText?: boolean }): string {
  if (value == null || value === "") return "—";
  if (value === "skipped") return "Skipped";
  if (value === "other" || value.startsWith("other:")) {
    const text = value.startsWith("other:") ? value.slice("other:".length).trim() : "";
    return opts?.withOtherText && text ? `Other — ${text}` : "Other";
  }
  return HEARD_LABELS[value] ?? value;
}

/** Bucket key used by the aggregate: every "other:<text>" collapses to "other". */
export function heardBucket(value: string): string {
  return value.startsWith("other:") ? "other" : value;
}
