import fs from "node:fs";
import path from "node:path";
import Image from "next/image";
// Namespace import (never named): a computed key lookup can't produce a
// "export not found" build error, so an unknown/removed brand simply resolves
// to `undefined` at runtime and falls through to the wordmark — the component
// therefore ALWAYS renders something professional. `simple-icons` is a build
// dependency (see package.json); it resolves during `npm install` on staging.
import * as simpleIcons from "simple-icons";

/**
 * Brand mark for a competitor on the /compare surface. Resolution order, so it
 * always renders something clean on the dark theme:
 *
 *   1. `/public/logos/<slug>.svg` when an operator has dropped a real logo in.
 *   2. The Simple Icons glyph for the brand, tinted with `currentColor` (slate)
 *      so it reads on navy rather than fighting it with the brand's own hex.
 *   3. A styled wordmark pill (the competitor's name) — the graceful fallback
 *      for brands Simple Icons doesn't carry (Contabo, Cloudways, Kamatera…).
 *
 * Nxeon's own mark (`slug="nxeon"`) renders the wordmark PNG at /public/logo.png.
 * This is a server component: the fs check and icon lookup never reach the client.
 */

type SimpleIcon = { title: string; slug: string; hex: string; path: string };

// slug → Simple Icons export key. Unknown/removed keys resolve to undefined and
// fall through to the wordmark, so listing an optimistic key is always safe.
const SI_KEY: Record<string, string> = {
  digitalocean: "siDigitalocean",
  hostinger: "siHostinger",
  hetzner: "siHetzner",
  linode: "siLinode",
  ovh: "siOvh",
  vultr: "siVultr",
  aws: "siAmazonwebservices",
  godaddy: "siGodaddy",
  bluehost: "siBluehost",
  namecheap: "siNamecheap",
  hostgator: "siHostgator",
  ionos: "siIonos",
  a2hosting: "siA2hosting",
  // No Simple Icons brand mark — these intentionally use the wordmark fallback:
  //   contabo, cloudways, kamatera
};

/** Does an operator-supplied SVG exist at /public/logos/<slug>.svg? */
function hasPublicLogo(slug: string): boolean {
  try {
    return fs.existsSync(path.join(process.cwd(), "public", "logos", `${slug}.svg`));
  } catch {
    return false;
  }
}

/** Look up the Simple Icons glyph for a slug, or null if the brand isn't carried. */
function simpleIcon(slug: string): SimpleIcon | null {
  const key = SI_KEY[slug];
  if (!key) return null;
  const icon = (simpleIcons as Record<string, unknown>)[key] as SimpleIcon | undefined;
  return icon && typeof icon.path === "string" ? icon : null;
}

export function CompetitorLogo({
  slug,
  name,
  /** Target mark height in px; the wordmark scales its text to match. */
  size = 40,
  className = "",
}: {
  slug: string;
  name: string;
  size?: number;
  className?: string;
}) {
  // Nxeon's own wordmark PNG (wide lockup — contain it within the height).
  if (slug === "nxeon") {
    return (
      <Image
        src="/logo.png"
        alt="Nxeon"
        width={496}
        height={85}
        className={`w-auto object-contain ${className}`}
        style={{ height: size }}
        priority={false}
      />
    );
  }

  if (hasPublicLogo(slug)) {
    // Operator-supplied real logo. next/image with a plain <img> semantics via
    // unoptimized keeps SVGs crisp without extra domain config.
    // eslint-disable-next-line @next/next/no-img-element
    return (
      <img
        src={`/logos/${slug}.svg`}
        alt={name}
        style={{ height: size }}
        className={`w-auto object-contain ${className}`}
      />
    );
  }

  const icon = simpleIcon(slug);
  if (icon) {
    return (
      <svg
        role="img"
        aria-label={name}
        viewBox="0 0 24 24"
        style={{ height: size, width: size }}
        className={`text-slate-200 ${className}`}
      >
        <title>{name}</title>
        <path d={icon.path} fill="currentColor" />
      </svg>
    );
  }

  // Wordmark fallback — a clean logotype so the layout never looks broken. Plain
  // styled text (no pill) composes inside the hero tiles, table headers and hub
  // cards without nesting a box in a box, and scales with `size`.
  return (
    <span
      className={`inline-flex items-center whitespace-nowrap font-semibold tracking-tight text-slate-100 ${className}`}
      style={{ fontSize: Math.round(size * 0.62), lineHeight: 1 }}
    >
      {name}
    </span>
  );
}
