"use client";

import { useState, useTransition } from "react";
import { createPortal } from "react-dom";
// Namespace import (never named): a computed key lookup can't produce an
// "export not found" build error, so an unknown/removed brand simply renders
// nothing and the button falls back to its plain label. Same pattern as
// components/marketing/CompetitorLogo.tsx.
import * as simpleIcons from "simple-icons";
import { IconUsers } from "@/components/marketing/icons";
import { setHeardAboutUs } from "@/lib/actions-account";
import { HEARD_OPTIONS, HEARD_OTHER_MAX } from "@/lib/heard-about";

type SimpleIcon = { title: string; slug: string; hex: string; path: string };

/** Channel key → Simple Icons export name, for the real platforms we can
 *  scrape an accurate vector brand mark for. `color` overrides the brand's
 *  own hex only when that hex is near-black (TikTok, X) and would otherwise
 *  vanish on this modal's dark card background. */
const HEARD_BRAND_ICON: Record<string, { key: string; color?: string }> = {
  google: { key: "siGoogle" },
  youtube: { key: "siYoutube" },
  instagram: { key: "siInstagram" },
  tiktok: { key: "siTiktok", color: "#FFFFFF" },
  facebook: { key: "siFacebook" },
  x: { key: "siX", color: "#FFFFFF" },
  reddit: { key: "siReddit" },
};

/** Real vector brand mark for a platform channel, or null when the key isn't
 *  one of the platforms above (the non-platform options use hand-drawn line
 *  icons instead — see below). */
function BrandIcon({ channelKey, size = 22 }: { channelKey: string; size?: number }) {
  const entry = HEARD_BRAND_ICON[channelKey];
  const icon = entry ? ((simpleIcons as Record<string, unknown>)[entry.key] as SimpleIcon | undefined) : undefined;
  if (!icon || typeof icon.path !== "string") return null;
  return (
    <svg role="img" aria-hidden viewBox="0 0 24 24" style={{ height: size, width: size }}>
      <path d={icon.path} fill={entry?.color ?? `#${icon.hex}`} />
    </svg>
  );
}

/** Shared stroke style for the non-platform line icons below — same visual
 *  language as components/marketing/icons.tsx and PaymentStep.tsx's inline
 *  icons (24×24, stroke=currentColor), so they inherit the button's text
 *  color and adapt to the selected state automatically. */
function LineIcon({ size = 22, children }: { size?: number; children: React.ReactNode }) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.7"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
    >
      {children}
    </svg>
  );
}

function BlogIcon(p: { size?: number }) {
  return (
    <LineIcon {...p}>
      <rect x="4" y="3" width="16" height="18" rx="2" />
      <path d="M8 8h8M8 12h8M8 16h5" />
    </LineIcon>
  );
}

function OtherIcon(p: { size?: number }) {
  return (
    <LineIcon {...p}>
      <circle cx="12" cy="12" r="9" />
      <path d="M9.4 9.2a2.6 2.6 0 1 1 3.7 2.35c-.85.4-1.1.95-1.1 1.75" />
      <circle cx="12" cy="16.9" r="0.9" fill="currentColor" stroke="none" />
    </LineIcon>
  );
}

/** Icon for a HEARD_OPTIONS key (or "other"): the real brand mark for a
 *  platform, a matching line icon for the non-platform options, or null. */
function optionIcon(key: string): React.ReactNode {
  if (HEARD_BRAND_ICON[key]) return <BrandIcon channelKey={key} />;
  if (key === "friend") return <IconUsers size={22} />;
  if (key === "blog") return <BlogIcon />;
  if (key === "other") return <OtherIcon />;
  return null;
}

