import "dotenv/config";
import { SignJWT } from "jose";
import { PrismaClient } from "@prisma/client";

const EMAIL = "claude-audit-2026@nxeon.test";

const db = new PrismaClient();
const secret = new TextEncoder().encode(process.env.AUTH_SECRET);
const cookieName = process.env.NXEON_COOKIE_NAME ?? "nxeon_session";

const user = await db.user.findUnique({ where: { email: EMAIL }, select: { id: true, sessionVersion: true } });
if (!user) {
  console.error("Test account not found:", EMAIL);
  process.exit(1);
}

// Reset the one-time survey gate so the modal shows again for this pass.
await db.user.update({ where: { id: user.id }, data: { heardAboutUs: null } });

const token = await new SignJWT({ sub: user.id, sv: user.sessionVersion ?? 0, typ: "session" })
  .setProtectedHeader({ alg: "HS256" })
  .setIssuedAt()
  .setExpirationTime("1h")
  .sign(secret);

console.log(JSON.stringify({ cookieName, token, userId: user.id }));
await db.$disconnect();

