export async function register(prev: any, formData: FormData): Promise<{ error?: string }> {
  const parsed = credsSchema
    .extend({
      name: z.string().min(1, "Enter your name").max(100, "Name is too long"),
      password: z
        .string()
        .min(8, "Password must be at least 8 characters")
        .max(200, "Password is too long")
        .regex(/[a-zA-Z]/, "Password must include a letter")
        .regex(/[0-9]/, "Password must include a number"),
    })
    .safeParse({
    // Canonicalise BEFORE validating, so `  Alice@Example.com ` is stored in the
    // one form every lookup will use. See lib/email-normalize.ts.
    email: normalizeEmail(formData.get("email")),
    password: formData.get("password"),
    name: formData.get("name"),
  });
  // Say what is actually wrong. This used to collapse four precise, already
  // written messages into "Enter a valid email, name, and password (min 8
  // chars)." — so a customer whose only problem was a missing digit was told
  // about a length rule their 8-character password already satisfied, and had
  // no way to work out what the form wanted. The deploy path (`payAndDeploy`
  // below, via lib/order.ts) has surfaced the real issue since it was written;
  // this is the same one line.
  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Check the form and try again." };
